1312|static int _json_object_set_string_len(json_object *jso, const char *s, size_t len)
1313|{
1314|	char *dstbuf;
1315|	ssize_t curlen;
1316|	ssize_t newlen;
1317|	if (jso == NULL || jso->o_type != json_type_string)
1318|		return 0;
1319|
1320|	if (len >= INT_MAX - 1)
1321|		// jso->len is a signed ssize_t, so it can't hold the
1322|		// full size_t range. json_object_get_string_len returns
1323|		// length as int, cap length at INT_MAX.
1324|		return 0;
1325|
1326|	curlen = JC_STRING(jso)->len;
1327|	if (curlen < 0) {
1328|		if (len == 0) {
1329|			free(JC_STRING(jso)->c_string.pdata);
1330|			JC_STRING(jso)->len = curlen = 0;
1331|		} else {
1332|			curlen = -curlen;
1333|		}
1334|	}
1335|
1336|	newlen = len;
1337|	dstbuf = get_string_component_mutable(jso);
1338|
1339|	if ((ssize_t)len > curlen)
1340|	{
1341|		// We have no way to return the new ptr from realloc(jso, newlen)
1342|		// and we have no way of knowing whether there's extra room available
1343|		// so we need to stuff a pointer in to pdata :(
1344|		dstbuf = (char *)malloc(len + 1);
1345|		if (dstbuf == NULL)
1346|			return 0;
1347|		if (JC_STRING(jso)->len < 0)
1348|			free(JC_STRING(jso)->c_string.pdata);
1349|		JC_STRING(jso)->c_string.pdata = dstbuf;
1350|		newlen = -(ssize_t)len;
1351|	}
1352|	else if (JC_STRING(jso)->len < 0)
1353|	{
1354|		// We've got enough room in the separate allocated buffer,
1355|		// so use it as-is and continue to indicate that pdata is used.
1356|		newlen = -(ssize_t)len;
1357|	}
1358|
1359|	memcpy(dstbuf, (const void *)s, len);
1360|	dstbuf[len] = '\0';
1361|	JC_STRING(jso)->len = newlen;
1362|	return 1;
